{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "A high proportion of SARS-CoV-2 patients survive infection but the prevalence of chronic sequelae and resulting disability is increasing. These survivors need clinical management and rehabilitation to facilitate good health outcomes. The best available research evidence is required to inform management and rehabilitation decisions, interventions, and health systems for COVID-19 survivors with adverse clinical sequelae. Further evidence is warranted to estimate the resources needed to plan for setting appropriate and adequately delivered post-acute and long-term rehabilitation services.",
      "reason": "Explicit description of the current state (increasing prevalence of chronic sequelae, survivors' needs) and identification of important uncertainties/gaps (need for evidence to inform management, resource estimation, and rehabilitation services)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "The best available research evidence is required to inform management and rehabilitation decisions, interventions, and health systems for COVID-19 survivors with adverse clinical sequelae. Further evidence is warranted to estimate the resources needed to plan for setting appropriate and adequately delivered post-acute and long-term rehabilitation services.",
      "reason": "The manuscript states the importance and need for the review: to provide best-available evidence to inform clinical management, interventions, health systems, and resource planning for rehabilitation of COVID-19 survivors."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The methodology of this systematic review updates the second edition published in June 2020. It follows the Preferred Reporting Items for Systematic Reviews and Meta-Analyses (PRISMA) Guidelines ... The protocol has been updated in PROSPERO (CRD42021181202). ... The search strategy, screening, and data extraction criteria were not changed from the previous edition except for the exclusion of case reports and case series.",
      "reason": "The authors explicitly state this edition updates prior editions (including a second edition) and reference updating the protocol in PROSPERO, explaining how the current review relates to and modifies previous reviews."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No text in the provided evidence describes a proposed mechanism of action for rehabilitation interventions; while some included studies report intervention effectiveness, the review does not present a brief mechanism of action."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence in the provided text indicates that a logic model was considered or presented for complex interventions or delivery contexts."
    }
  ],
  "confidence": 85
}

