{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "The search strategy, screening, and data extraction criteria were not changed from the previous edition 4 except for the exclusion of case reports and case series. Additionally, to manage discrepancies encountered in past editions between the study design declared by the authors and the actual design of the study, we classified study designs according to the Agency for Healthcare Research and Quality 7 (Supplementary Digital Material 1: Supplementary Text File 1).",
      "reason": "The manuscript specifies some study characteristics used for eligibility (exclusion of case reports and case series; classification of study designs) and that all participants were COVID survivors (text_6). However, it does not fully specify all study-characteristic eligibility components (e.g., complete list of eligible study designs, settings, explicit follow-up requirements) in the provided evidence."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": \"EVidEncE acQuisition: studies published from May 1 st to June 30 th , 2021 were selected, excluding descriptive studies and expert opinions.\",
      "reason": "The review reports the date range for included publications and exclusions of certain report types (descriptive studies, expert opinions, and exclusion of case reports/series noted elsewhere), but the provided evidence does not state eligibility by language or fuller publication/report-status criteria."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit information in the provided evidence distinguishes exclusion because outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_5",
      "quote": "Table I, II, and III synthesize the distribution of selected studies by geographical area (Table I), limitations of functioning of rehabilitation interest (LFRI), disease phase and rehabilitation setting (Table II), research question, and study design (Table III). 12-36",
      "reason": "The review specifies groups used to summarize included studies (e.g., by research question, LFRI, disease phase, study design) and reports a narrative synthesis by research question. However, the provided evidence does not explicitly link these groups to specific comparisons defined in the review objectives or fully describe how groups were used in each synthesis."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_15",
      "quote": \"In this third edition, one modification was introduced to the selection criteria to narrow the breadth of findings and increase the level of evidence sought by excluding case reports and case series.\",
      "reason": "The manuscript provides a rationale for a notable restriction on study eligibility (excluding case reports and case series) explaining it was intended to narrow breadth and increase level of evidence."
    }
  ],
  "confidence": 75
}

